// File: /Users/sacino/musclehacking/src/features/calculator/Calculator.tsx, Lines 301-310

async function copyResults(): Promise<void> {
  if (!calculation.ok || !navigator.clipboard) return;

  const result = calculation.value;
  const text = buildResultText(result);

  await navigator.clipboard.writeText(text);
  setCopyStatus("Results copied.");
}
